C320_R = [("for (const dx of [-1.5, -0.5, 0.5, 1.5]) { const s = man(C9, 'soldier', cx9 + dx, C9.z1 - 6.6, 0.5); s.post = s.area; s.noMaster = true; enterNormal(s); } for (const dx of [-0.8, 0.8]) { const n = man(C9, 'sniper', cx9 + dx, C9.z1 - 8.0, 0.4); n.post = n.area; enterNormal(n); }", "const sn9 = [-0.8, 0.8].map((dx) => { const n = man(C9, 'sniper', cx9 + dx, C9.z1 - 8.0, 0.4); n.post = n.area; enterNormal(n); return n; }); [-1.5, -0.5, 0.5, 1.5].forEach((dx, i) => { const s = man(C9, 'soldier', cx9 + dx, C9.z1 - 6.6, 0.5); s.master = sn9[i < 2 ? 0 : 1]; s.slotA = Math.random() * Math.PI * 2; s.slotK = rand(0.5, 1); enterNormal(s); });   /* c320: 군인은 반씩 나눠 저격수 하나씩 호위 (큰 맵 호위와 같다) */"), ("for (const dz of [-0.8, 0.8]) { const s = man(C10, 'soldier', mx - 0.7, mz + dz, 0.5); s.post = s.area; s.noMaster = true; enterNormal(s); } { const n = man(C10, 'sniper', mx + 0.7, mz, 0.4); n.post = n.area; enterNormal(n); }", "const sn10 = man(C10, 'sniper', mx + 0.7, mz, 0.4); sn10.post = sn10.area; enterNormal(sn10); for (const dz of [-0.8, 0.8]) { const s = man(C10, 'soldier', mx - 0.7, mz + dz, 0.5); s.master = sn10; s.slotA = Math.random() * Math.PI * 2; s.slotK = rand(0.5, 1); enterNormal(s); }   /* c320: 군인 둘 다 저격수 호위 */")]
